parameters.functionScript:
 let words = ["económica", "eficaz", "rapida"];
let currentWord = 0;
let currentIndex = 0;
let isDeleting = false;

function typeWord() {
    let fullText = words[currentWord];

    if (isDeleting) {
        Noodl.Variables.typedText = fullText.substring(0, currentIndex--);
    } else {
        Noodl.Variables.typedText = fullText.substring(0, currentIndex++)+ "|";
    }

    if (!isDeleting && currentIndex > fullText.length) {
        isDeleting = true;
        setTimeout(typeWord, 1000); // pausa antes de borrar
        return;
    } else if (isDeleting && currentIndex < 0) {
        isDeleting = false;
        currentWord = (currentWord + 1) % words.length;
    }

    setTimeout(typeWord, isDeleting ? 50 : 100);
}

typeWord();

