function initCarousel() {
  const c = document.querySelector('.carrusel');
  if (!c) {
    // si aún no está en el DOM, intenta de nuevo
    setTimeout(initCarousel, 300);
    return;
  }

  const pasos = document.querySelectorAll('.slide');
  let idx = 0;
  const total = pasos.length;

  function avanzar() {
    idx = (idx + 1) % total;
    // desplazarse hasta la posición X del slide idx
    c.scrollLeft = pasos[idx].offsetLeft;
  }

  // arranca el loop
  setInterval(avanzar, 3000);
}

initCarousel();

parameters.style:
/* Contenedor principal: solo un slide visible */
.carrusel {
  width: 300px;
  overflow: hidden;
  position: relative;
}

/* Las slides van en una pista flexible */
.carrusel .slides {
  display: flex;
  transition: transform 0.5s ease;
}

/* Cada slide ocupa el 100% del contenedor */
.carrusel .slide {
  flex: 0 0 100%;
}

